import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,ag as o}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse(`{"title":"Tailscale learning map","description":"Tailscale is an encrypted network in which devices signed in to the same account can reach each other. This page is the product overview plus a decision table: it first answers 'what do I want to connect, and which feature should I use', then points to the tutorial and the source-code page.","frontmatter":{"title":"Tailscale learning map","description":"Tailscale is an encrypted network in which devices signed in to the same account can reach each other. This page is the product overview plus a decision table: it first answers 'what do I want to connect, and which feature should I use', then points to the tutorial and the source-code page.","domain":"product","tags":["mesh-vpn","remote-access","tailscale"],"role":"map"},"headers":[],"relativePath":"products/tailscale/index.md","filePath":"products/tailscale/index.md","lastUpdated":1795764761000}`),i={name:"products/tailscale/index.md"};function s(l,t,n,d,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="tailscale-learning-map" tabindex="-1">Tailscale learning map <a class="header-anchor" href="#tailscale-learning-map" aria-label="Permalink to &quot;Tailscale learning map&quot;">​</a></h1><blockquote><p><strong>The short version:</strong> Tailscale lets <strong>devices signed in to the same account</strong> reach each other. Data is encrypted end to end, and no public IP address or port forwarding is needed. It is a collection of features, not a single product: first work out &quot;what you want to connect&quot;, then choose one of the rows below.</p><p>Official definition (<a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>): an identity-based zero-trust connectivity platform that uses the open source WireGuard protocol to build encrypted point-to-point connections and form a peer-to-peer network called a <strong>tailnet</strong>. This page is the <strong>map</strong>; for hands-on work, go to the <a href="./tailscale.html">tutorial</a>.</p></blockquote><h2 id="audience-prerequisites-non-goals" tabindex="-1">Audience / prerequisites / non-goals <a class="header-anchor" href="#audience-prerequisites-non-goals" aria-label="Permalink to &quot;Audience / prerequisites / non-goals&quot;">​</a></h2><ul><li><strong>Who:</strong> frontend or AI application developers who want to reach another device of their own (a desktop, a laptop, a NAS, a VM in the cloud) from outside, without having to study networking.</li><li><strong>Prerequisites:</strong> an account with an identity provider (one of Google, GitHub, Microsoft, Apple, Okta, OneLogin, or a custom OpenID Connect provider); two devices.</li><li><strong>Non-goals:</strong><ul><li>Not a tool for changing your apparent location or getting around regional blocks. A self-hosted exit node only moves the exit point to a device of your own.</li><li>Does not cover the cryptography of WireGuard itself.</li><li>Advanced topics such as Kubernetes Operator, Tailnet Lock and OAuth clients get one row each on this page, with official links only.</li></ul></li></ul><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>The &quot;official names&quot; in the table below are copied from the official documentation index (<a href="https://tailscale.com/docs/llms.txt" target="_blank" rel="noreferrer">Tailscale Documentation</a>) opened on 2026-11-24. This directory has only three pages: this map, the <a href="./tailscale.html">tutorial</a> and the <a href="./source.html">source-code walkthrough</a>.</p><table tabindex="0"><thead><tr><th>Official name</th><th>Official URL</th><th>Where it goes on this site</th></tr></thead><tbody><tr><td><strong>Install Tailscale on Windows / macOS / Linux / iOS / Android</strong></td><td><a href="https://tailscale.com/docs/install/windows" target="_blank" rel="noreferrer">Windows</a> · <a href="https://tailscale.com/docs/install/mac" target="_blank" rel="noreferrer">macOS</a> · <a href="https://tailscale.com/docs/install/linux" target="_blank" rel="noreferrer">Linux</a> · <a href="https://tailscale.com/docs/install/ios" target="_blank" rel="noreferrer">iOS</a> · <a href="https://tailscale.com/docs/install/android" target="_blank" rel="noreferrer">Android</a></td><td>Tutorial, the Install section</td></tr><tr><td><strong>Tailscale CLI</strong></td><td><a href="https://tailscale.com/docs/reference/tailscale-cli" target="_blank" rel="noreferrer">tailscale.com/docs/reference/tailscale-cli</a></td><td>Used throughout the tutorial; <code>--help</code> is the source of truth for flags</td></tr><tr><td><strong>Tailscale SSH</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-ssh" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-ssh</a></td><td>Tutorial, &quot;Everyday use&quot; and &quot;Security and privacy essentials&quot;</td></tr><tr><td><strong>Tailscale Serve</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-serve" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-serve</a></td><td>Tutorial, &quot;Everyday use&quot;</td></tr><tr><td><strong>Tailscale Funnel</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-funnel" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-funnel</a></td><td>The tutorial covers the guardrails only; it does not teach how to turn Funnel on</td></tr><tr><td><strong>Subnet routers</strong></td><td><a href="https://tailscale.com/docs/features/subnet-routers" target="_blank" rel="noreferrer">tailscale.com/docs/features/subnet-routers</a></td><td>Tutorial, &quot;Everyday use&quot;</td></tr><tr><td><strong>Exit nodes (route all traffic)</strong></td><td><a href="https://tailscale.com/docs/features/exit-nodes" target="_blank" rel="noreferrer">tailscale.com/docs/features/exit-nodes</a></td><td>Tutorial, &quot;Everyday use&quot; and &quot;Security and privacy essentials&quot;</td></tr><tr><td><strong>Mullvad exit nodes</strong> (paid add-on, beta)</td><td><a href="https://tailscale.com/docs/features/exit-nodes/mullvad-exit-nodes" target="_blank" rel="noreferrer">tailscale.com/docs/features/exit-nodes/mullvad-exit-nodes</a></td><td>One row on the map: use Mullvad&#39;s servers as the exit instead of a device of your own</td></tr><tr><td><strong>Tailscale Peer Relays</strong></td><td><a href="https://tailscale.com/docs/features/peer-relay" target="_blank" rel="noreferrer">tailscale.com/docs/features/peer-relay</a></td><td>One row on the map: when a direct connection fails, another device in the tailnet acts as the relay</td></tr><tr><td><strong>Taildrop</strong> (alpha)</td><td><a href="https://tailscale.com/docs/features/taildrop" target="_blank" rel="noreferrer">tailscale.com/docs/features/taildrop</a></td><td>Tutorial, &quot;Everyday use&quot;</td></tr><tr><td><strong>MagicDNS</strong></td><td><a href="https://tailscale.com/docs/features/magicdns" target="_blank" rel="noreferrer">tailscale.com/docs/features/magicdns</a></td><td>Tutorial, &quot;Everyday use&quot;</td></tr><tr><td><strong>admin console and tailnet policy file</strong> (formerly called ACL; the newer form is grants)</td><td><a href="https://tailscale.com/docs/features/tailnet-policy-file" target="_blank" rel="noreferrer">tailnet-policy-file</a> · <a href="https://tailscale.com/docs/features/access-control" target="_blank" rel="noreferrer">Access control</a></td><td>Tutorial, &quot;Security and privacy essentials&quot;</td></tr><tr><td><strong>Group devices with tags</strong></td><td><a href="https://tailscale.com/docs/features/tags" target="_blank" rel="noreferrer">tailscale.com/docs/features/tags</a></td><td>One row on the map; one row in the tutorial&#39;s glossary</td></tr><tr><td><strong>Key expiry</strong></td><td><a href="https://tailscale.com/docs/features/access-control/key-expiry" target="_blank" rel="noreferrer">tailscale.com/docs/features/access-control/key-expiry</a></td><td>Tutorial, &quot;Security and privacy essentials&quot;</td></tr><tr><td><strong>Device approval</strong></td><td><a href="https://tailscale.com/docs/features/access-control/device-management/device-approval" target="_blank" rel="noreferrer">tailscale.com/docs/features/access-control/device-management/device-approval</a></td><td>Tutorial, &quot;Security and privacy essentials&quot;</td></tr><tr><td><strong>Personal / Standard / Premium / Enterprise</strong> (plans)</td><td><a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">tailscale.com/pricing</a></td><td>Tutorial, &quot;Pricing, quotas and limits&quot;</td></tr><tr><td><strong>Tailscale SSH session recording</strong></td><td><a href="https://tailscale.com/docs/features/tsrecorder" target="_blank" rel="noreferrer">tailscale.com/docs/features/tsrecorder</a></td><td>One row on the map: record SSH sessions and store them on a recorder node of your own</td></tr><tr><td><strong>tsnet</strong></td><td><a href="https://tailscale.com/docs/features/tsnet" target="_blank" rel="noreferrer">tailscale.com/docs/features/tsnet</a></td><td>One row on the map: embed Tailscale in a Go program</td></tr><tr><td><strong>Tailscale Kubernetes Operator</strong></td><td><a href="https://tailscale.com/docs/kubernetes-operator" target="_blank" rel="noreferrer">tailscale.com/docs/kubernetes-operator</a></td><td>One row on the map</td></tr><tr><td><strong>Tailnet Lock</strong></td><td><a href="https://tailscale.com/docs/features/tailnet-lock" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailnet-lock</a></td><td>One row on the map: a new node can join only after a node you designate has signed it</td></tr><tr><td><strong>OAuth clients</strong></td><td><a href="https://tailscale.com/docs/features/oauth-clients" target="_blank" rel="noreferrer">tailscale.com/docs/features/oauth-clients</a></td><td>One row on the map: let a program keep accessing the Tailscale API</td></tr><tr><td><strong>Aperture by Tailscale / Tailscale PAM</strong></td><td><a href="https://tailscale.com/docs/aperture/what-is-aperture" target="_blank" rel="noreferrer">Aperture</a> · <a href="https://tailscale.com/docs/privileged-access-management/what-is-tailscale-pam" target="_blank" rel="noreferrer">PAM</a></td><td>One row on the map: two other products from the same company, not part of &quot;connecting devices&quot;</td></tr></tbody></table><h3 id="personal-vs-organization-who-owns-the-tailnet" tabindex="-1">Personal vs. organization: who owns the tailnet <a class="header-anchor" href="#personal-vs-organization-who-owns-the-tailnet" aria-label="Permalink to &quot;Personal vs. organization: who owns the tailnet&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Sign up with a public email address (for example Gmail or a personal GitHub account)</td><td>Treated as personal use; the account goes into the free Personal plan automatically</td></tr><tr><td>Sign up with a custom domain</td><td>Treated as business use; the account goes into the 14-day Enterprise trial automatically</td></tr><tr><td>The tailnet uses a custom domain</td><td>Users with an email address under the same domain can sign in without an invitation; everyone else needs an external invitation</td></tr><tr><td>One device should belong to both a personal tailnet and a company tailnet</td><td>A device can be registered to several tailnets and you switch between them in the client; but a node belongs to only one tailnet at a time</td></tr></tbody></table><p>Sources: <a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">Tailscale pricing</a> FAQ, <a href="https://tailscale.com/docs/how-to/quickstart" target="_blank" rel="noreferrer">Tailscale quickstart</a>, <a href="https://tailscale.com/docs/concepts/tailscale-identity" target="_blank" rel="noreferrer">Tailscale identity</a>.</p><h3 id="names-that-collide" tabindex="-1">Names that collide <a class="header-anchor" href="#names-that-collide" aria-label="Permalink to &quot;Names that collide&quot;">​</a></h3><ul><li><strong>Tailscale is not a traditional VPN.</strong> The official comparison: in a traditional VPN all traffic passes through a central gateway, which may be far from the user, adds latency and becomes a bottleneck; Tailscale lets devices connect to each other directly. You can still use it as a traditional VPN through an exit node.</li><li><strong>Tailscale is not WireGuard itself.</strong> WireGuard is the protocol. Official statement: Tailscale is built on WireGuard and adds NAT traversal, TCP transport and access policy.</li><li><strong>Tailscale SSH is not ordinary SSH.</strong> It takes over port 22 on the target machine&#39;s Tailscale IP and authenticates with the Tailscale identity instead of a key pair.</li><li><strong>Serve is not Funnel.</strong> Serve makes a service visible only inside the tailnet; Funnel makes it visible to the whole internet.</li><li><strong>An exit node is not a subnet router.</strong> The first forwards all of your internet traffic; the second lets you reach a private subnet and leaves your internet traffic alone.</li><li><strong>Taildrop is not Taildrive.</strong> The first sends files between your own devices; the second shares folders inside the tailnet (they get one row each on this page, <a href="https://tailscale.com/docs/features/taildrive" target="_blank" rel="noreferrer">Taildrive</a>).</li><li><strong>Tailscale is not Aperture, and it is not Tailscale PAM.</strong> Those two are the same company&#39;s AI gateway product and privileged access management product.</li></ul><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><h3 id="without-tailscale-vs-with-tailscale" tabindex="-1">Without Tailscale vs. with Tailscale <a class="header-anchor" href="#without-tailscale-vs-with-tailscale" aria-label="Permalink to &quot;Without Tailscale vs. with Tailscale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What I want to do</th><th>The traditional way</th><th>With Tailscale</th></tr></thead><tbody><tr><td>Reach another device at home or at the office from outside</td><td>A public IP address plus port forwarding on the router, or a self-hosted VPN server</td><td>Sign in to the same account and connect directly by device name or <code>100.x.y.z</code> address</td></tr><tr><td>SSH into my own machine</td><td>Generate a key pair, then distribute the public key to the target machine</td><td>Tailscale SSH authorizes by tailnet policy, so no public key has to be distributed</td></tr><tr><td>Show the dev server on this machine to someone else</td><td>Deploy to the public internet, or set up a tunnel into the private network</td><td><code>tailscale serve</code>, open to the tailnet only</td></tr><tr><td>Reach a device at home that has no client installed</td><td>Set up port forwarding separately for each device</td><td>One subnet router forwards the traffic on their behalf</td></tr><tr><td>Encrypt communication between two devices</td><td>Configure WireGuard yourself and generate and distribute keys by hand</td><td>Keys are generated and distributed automatically after sign-in</td></tr></tbody></table><p>The &quot;traditional way&quot; column comes from the official page&#39;s comparison: connections need no port forwarding or complicated firewall rules, and when WireGuard is used without Tailscale the user has to generate and distribute keys by hand.</p><h3 id="compared-with-the-alternatives" tabindex="-1">Compared with the alternatives <a class="header-anchor" href="#compared-with-the-alternatives" aria-label="Permalink to &quot;Compared with the alternatives&quot;">​</a></h3><p>Only facts that can be backed by an official page are listed.</p><table tabindex="0"><thead><tr><th>Option</th><th>Traffic path</th><th>Keys and identity</th><th>Basis</th></tr></thead><tbody><tr><td>Traditional VPN (central gateway)</td><td>All of it goes through the gateway</td><td>Configured by the administrator</td><td>The gateway may be far from the user, so latency is higher; funneling everything through one point makes it a bottleneck</td></tr><tr><td>WireGuard configured by hand</td><td>Between the endpoints</td><td>Keys generated and distributed by hand</td><td>The official docs list it as work Tailscale automates for the user</td></tr><tr><td>Tailscale</td><td>Direct when possible, DERP relay when not</td><td>Sign in with an identity provider; keys distributed automatically</td><td>All three connection types are end-to-end encrypted</td></tr><tr><td>Self-hosted coordination server (such as Headscale)</td><td>Same as the Tailscale client</td><td>Same as Tailscale</td><td>The official docs have a page on switching clients to a self-hosted control server</td></tr><tr><td>Screen-streaming remote desktop</td><td>Not applicable</td><td>Not applicable</td><td>Solves a different problem: seeing and operating another machine&#39;s screen, see <a href="./../uu-remote/">UU Remote</a></td></tr></tbody></table><p>Sources: <a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>, <a href="https://tailscale.com/docs/concepts/wireguard" target="_blank" rel="noreferrer">About WireGuard</a>, <a href="https://tailscale.com/docs/concepts/tailscale-identity" target="_blank" rel="noreferrer">Tailscale identity</a>, <a href="https://tailscale.com/docs/reference/connection-types" target="_blank" rel="noreferrer">Connection types</a>, <a href="https://tailscale.com/docs/how-to/set-up-custom-coordination-server" target="_blank" rel="noreferrer">custom control server</a>.</p><h2 id="quick-decision-which-feature-fits-my-situation" tabindex="-1">Quick decision: which feature fits my situation <a class="header-anchor" href="#quick-decision-which-feature-fits-my-situation" aria-label="Permalink to &quot;Quick decision: which feature fits my situation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>My situation</th><th>What to use</th></tr></thead><tbody><tr><td>SSH back to my own Linux machine from outside</td><td>Tailscale SSH</td></tr><tr><td>The target is Windows, or the Mac App Store version on macOS</td><td>Install Tailscale, then use the built-in ordinary SSH or remote desktop and give the device name as the target</td></tr><tr><td>Show the dev server on this machine to people in the tailnet</td><td>Tailscale Serve</td></tr><tr><td>Open a service to the public internet</td><td>Tailscale Funnel; read the guardrails in the tutorial first</td></tr><tr><td>Reach a device at home that has no client installed (a printer, a NAS admin page)</td><td>Subnet router</td></tr><tr><td>Send traffic out through my home network while on public Wi-Fi</td><td>Exit node</td></tr><tr><td>Transfer files between my own devices</td><td>Taildrop</td></tr><tr><td>Add someone else to the tailnet</td><td>Tighten the tailnet policy file first</td></tr><tr><td>Keep a server or GPU machine online long term</td><td>Disable key expiry; the advanced approach is to tag the device</td></tr><tr><td>Stuck on a relay and too slow</td><td>Run <code>tailscale netcheck</code> first to see why, then consider Tailscale Peer Relays</td></tr><tr><td>Embed Tailscale in my own Go program</td><td>tsnet</td></tr><tr><td>Use it in a Kubernetes cluster</td><td>Tailscale Kubernetes Operator</td></tr></tbody></table><h2 id="how-to-read-this-directory" tabindex="-1">How to read this directory <a class="header-anchor" href="#how-to-read-this-directory" aria-label="Permalink to &quot;How to read this directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you can do after reading it</th><th>When to read it</th></tr></thead><tbody><tr><td><a href="./tailscale.html">Tutorial</a></td><td>Install two devices and confirm they can reach each other; sign in with Tailscale SSH; get Serve, subnet routing, exit node and Taildrop working; know the six guardrails</td><td>Now. No prerequisites</td></tr><tr><td><a href="./source.html">Source-code walkthrough</a></td><td>Explain how a connection is built in the code; understand how the CLI and the daemon communicate and how permissions are decided; know why <code>tailscale up</code> makes you repeat flags</td><td>After you are comfortable with the product, or when you need to investigate its internal behavior</td></tr><tr><td>This page</td><td>Pick a feature; look up the official entry point</td><td>Any time, for reference</td></tr></tbody></table><p>Recommended order: <strong>tutorial first, source code second.</strong> Do not skip the tutorial&#39;s security and privacy section, especially if you do not plan to be the only user.</p><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>: what it is, and whose problems it solves.</li><li><a href="https://tailscale.com/docs/reference/connection-types" target="_blank" rel="noreferrer">Connection types</a>: the order in which direct, DERP and Peer Relay connections are set up, and how to tell which one is in use.</li><li><a href="https://tailscale.com/docs/concepts/control-data-planes" target="_blank" rel="noreferrer">Control and data planes</a>: what the coordination server is and is not responsible for.</li><li><a href="https://tailscale.com/docs/concepts/can-tailscale-decrypt-traffic" target="_blank" rel="noreferrer">Can Tailscale decrypt my traffic?</a>: a short Q&amp;A page on traffic privacy.</li><li><a href="https://tailscale.com/docs/features/tailscale-ssh" target="_blank" rel="noreferrer">Tailscale SSH</a>: how it works, rule syntax, limits.</li><li><a href="https://tailscale.com/docs/features/tailscale-serve" target="_blank" rel="noreferrer">Tailscale Serve</a> and <a href="https://tailscale.com/docs/features/tailscale-funnel" target="_blank" rel="noreferrer">Tailscale Funnel</a>: how each works, and its limits.</li><li><a href="https://tailscale.com/docs/features/subnet-routers" target="_blank" rel="noreferrer">Subnet routers</a> and <a href="https://tailscale.com/docs/features/exit-nodes" target="_blank" rel="noreferrer">Exit nodes</a>: setup steps for each platform.</li><li><a href="https://tailscale.com/docs/features/tailnet-policy-file" target="_blank" rel="noreferrer">Tailnet policy file</a>: which sections the policy file has and what each one governs.</li><li><a href="https://tailscale.com/docs/reference/tailscale-cli" target="_blank" rel="noreferrer">Tailscale CLI</a>: all subcommands and flags.</li><li><a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">Tailscale pricing</a>: plans, add-ons and the billing FAQ.</li><li><a href="https://tailscale.com/docs/reference/best-practices/security" target="_blank" rel="noreferrer">Best practices to secure your tailnet</a>: the official security baseline and advanced checklist.</li><li><a href="https://tailscale.com/docs/llms.txt" target="_blank" rel="noreferrer">Tailscale Documentation</a>: the index of the whole official documentation; the source of the family table on this page.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./tailscale.html">Tutorial</a>: the hands-on tutorial in this directory.</li><li><a href="./source.html">Source-code walkthrough</a>: the source-level walkthrough in this directory.</li><li><a href="./../uu-remote/">UU Remote</a>: a remote desktop tool. Compare the two approaches: &quot;NAT traversal at the network layer so devices can reach each other&quot; and &quot;streaming the screen&quot;.</li><li><a href="./../t3code/">T3 Code</a>: its repository has <code>packages/tailscale</code>.</li><li><a href="./../cindy/">Cindy</a>, <a href="./../codex/dot.html">Codex dot</a>: sister pages from the same batch, on the theme of remote and agent workstations.</li><li><a href="/products/claude/">Claude</a>, <a href="/products/codex/">Codex</a>: agents that can run on a remote workstation.</li><li><a href="/products/ollama.html">Ollama</a>: an example of a local model service you may want to reach from outside.</li></ul>',29)])])}const b=e(i,[["render",s]]);export{g as __pageData,b as default};
